// Junta o que veio do Airtable com o documento pedido pelo app.
const pedido = $('Recebe pedido do app').first().json.body;
const documento = String(pedido.documento || '').replace(/\D/g, '');

// Sem resultado, o no do Airtable devolve um item vazio (ou um item de
// erro, se a busca falhou) — os dois casos ficam de fora deste filtro.
const achados = $input.all().filter((item) => item.json && item.json.id && !item.json.error);
const encontrado = achados.length > 0 ? achados[0].json : null;

// No Airtable v2.2 os campos vem dentro de .fields; nas versoes antigas
// vinham soltos na raiz. Aceito os dois para nao depender da versao.
const campos = encontrado ? (encontrado.fields || encontrado) : {};

return [{
  json: {
    documento,
    jaExiste: Boolean(encontrado),
    nome: campos.Razao_Social_Nome || '',
    buscarNaReceita: !encontrado && documento.length === 14,
  },
}];

// Monta a resposta final com os dados da Receita, quando vieram.
// Se a Receita falhou ou nao achou o CNPJ, seguimos assim mesmo: o app
// mostra o formulario em branco, que e melhor do que travar o cadastro.
const receita = $json || {};
const telefone = receita.ddd_telefone_1 || receita.ddd_telefone_2 || '';

// A BrasilAPI devolve 429 quando passa do limite de consultas por minuto.
// Nesse caso vale insistir; quando o CNPJ so nao existe, nao adianta.
const textoErro = receita.error ? JSON.stringify(receita.error) : '';
const excedeuLimite = /429|too many requests/i.test(textoErro);
const achou = Boolean(receita.razao_social);

const juntar = (partes, cola) => partes.map((p) => String(p || '').trim())
  .filter(Boolean).join(cola);

// O endereco da Receita vai pronto para virar o primeiro local do cadastro.
// A tabela de Locais nao tem campo de CEP, entao ele entra no proprio texto.
const cep = String(receita.cep || '').replace(/\D/g, '');
const cepFormatado = cep.length === 8 ? cep.slice(0, 5) + '-' + cep.slice(5) : cep;

const endereco = achou && (receita.logradouro || receita.municipio)
  ? {
      nome: 'Endereço do CNPJ',
      endereco: juntar([
        juntar([receita.descricao_tipo_de_logradouro, receita.logradouro], ' '),
        receita.numero,
        receita.complemento,
        cepFormatado ? 'CEP ' + cepFormatado : '',
      ], ', '),
      bairroCidade: juntar([
        receita.bairro,
        juntar([receita.municipio, receita.uf], ' - '),
      ], ' / '),
    }
  : null;

return [{
  json: {
    ok: true,
    jaExiste: false,
    entidade: null,
    receita: achou
      ? {
          razaoSocial: receita.razao_social || '',
          nomeFantasia: receita.nome_fantasia || '',
          email: receita.email || '',
          telefone,
        }
      : null,
    endereco,
    // O app mostra este texto em amarelo quando os campos vem em branco.
    avisoReceita: achou
      ? null
      : excedeuLimite
        ? 'Muitas consultas seguidas à Receita. Espere um minuto e tente de novo.'
        : 'Não encontrei este CNPJ na Receita. Preencha os dados à mão.',
    // Só o limite passa: insistir num CNPJ inexistente nao muda nada.
    podeTentarDeNovo: !achou && excedeuLimite,
  },
}];

// Resposta quando ja existe, ou quando e CPF (nao consultamos a Receita).
return [{
  json: {
    ok: true,
    jaExiste: Boolean($json.jaExiste),
    entidade: $json.jaExiste ? { nome: $json.nome } : null,
    receita: null,
    endereco: null,
  },
}];
